#include "EnvironmentReader.h"
#include "MonoSchema.h"
#include <iostream>
using namespace hs2;
int wmain(int argc,wchar_t** argv){try{if(argc!=4){std::cerr<<"Usage: hs2_environment_checks game cache classdata.tpk\n";return 2;}auto database=std::make_shared<UnityClassDatabase>(argv[3]);auto assets=std::make_shared<NativeGpuAssetStore>(std::vector<fs::path>{},argv[1],database);auto schemas=std::make_shared<NativeMonoSchema>(fs::path(argv[1])/"HoneySelect2_Data/Managed",database);assets->SetScriptSchema([weak=std::weak_ptr<NativeGpuAssetStore>(assets),schemas](const GpuAssetPointer& p,std::string_view version){auto store=weak.lock();if(!store)throw std::runtime_error("Expired test store.");auto script=store->Metadata(p);return schemas->Type(script.String("m_AssemblyName"),script.String("m_Namespace"),script.String("m_ClassName"),version);});std::vector<AssetSelection> selections;std::vector<std::string> diagnostics;auto environment=ReadCharacterEnvironment(argv[1],argv[2],*assets,selections,diagnostics);size_t effects=0;for(auto& profile:environment.Profiles)effects+=profile.Effects.size();if(environment.Camera.Children.empty()||environment.RenderSettings.Children.empty()||environment.Lights.empty()||environment.Profiles.empty()||effects==0)throw std::runtime_error("Incomplete real environment.");for(auto& selection:selections){auto reader=assets->Reader(selection.Reference.Bundle);bool shader=selection.Key.find("CTAA_")!=std::string::npos;auto pointer=reader->Find(selection.Reference.Asset,shader?48:selection.Key=="environment.skybox"?21:selection.Key=="environment.reflection"?89:28);if(!pointer.PathId)throw std::runtime_error("Invalid selected environment resource.");}std::cout<<"Real environment passed: lights="<<environment.Lights.size()<<" profiles="<<environment.Profiles.size()<<" effects="<<effects<<" selections="<<selections.size()<<" DHH="<<environment.DhhEnabled<<" BetterAA="<<environment.BetterAA<<"\n";for(auto& message:diagnostics)std::cout<<"diagnostic: "<<message<<"\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
